  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Ephesians: Grace, Unity and the Armor of God$j$, $j${"readings": [{"title": "Ephesians 2 (King James Version)", "url": "/portal/bible/Ephesians/2"}, {"title": "Ephesians 4 (King James Version)", "url": "/portal/bible/Ephesians/4"}, {"title": "Ephesians 6 (King James Version)", "url": "/portal/bible/Ephesians/6"}], "body": "Read Ephesians 2, Ephesians 4 and Ephesians 6 in the King James Version. Then read this lesson.\n\nEphesus was one of the great cities of Asia Minor, and Paul had spent about three years there teaching the Word. He wrote the letter to the Ephesians while he was in prison. Ephesians is a letter about the church. In chapter 2 Paul wrote that we are saved by grace through faith, and that salvation is the gift of God and not of works. In chapter 4 he urged believers to keep the unity of the Spirit in the bond of peace and to be kind and forgiving to one another. In chapter 6 he taught that believers face a spiritual battle and must put on the whole armor of God to stand against the devil.\n\nKey words: grace, workmanship, unity, armor, sword of the Spirit.\n\nYour task: (1) Write Ephesians 2:8 and 9 in your own words. (2) Tell why Paul urged believers to keep unity in Ephesians 4. (3) Name at least four pieces of the armor of God and tell what the sword of the Spirit is.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 4. We continue with the letters of Paul. Four of them, Ephesians, Philippians, Colossians and Philemon, were written while Paul was in prison, so they are often called the prison letters. Paul was chained, but the Word of God was not chained, and these letters have encouraged believers for almost two thousand years.\n\nEphesus was a major city of Asia Minor, famous for its great temple of the goddess Diana. Paul spent about three years there on his third journey, and a strong church was planted. Later he wrote this letter to help the believers understand who they are in Christ and how the church is to live.\n\nIn chapter 2 Paul gave one of the clearest statements of salvation in the Bible. Ephesians 2:8 says, For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Verse 9 adds, Not of works, lest any man should boast. We cannot save ourselves. Then verse 10 tells us what we are saved for. For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them. We are saved by grace, and then we are given good works to do.\n\nIn chapter 4 Paul turned to the life of the church. Ephesians 4:3 says, Endeavouring to keep the unity of the Spirit in the bond of peace. The church is not a building. It is one body. Verse 4 says, There is one body, and one Spirit, even as ye are called in one hope of your calling; And verse 32 gives a daily command, And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you. Unity grows when we forgive.\n\nChapter 6 teaches that the Christian life includes a spiritual battle. Ephesians 6:10 says, Finally, my brethren, be strong in the Lord, and in the power of his might. Verse 11 says, Put on the whole armour of God, that ye may be able to stand against the wiles of the devil. Verse 12 explains, For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places. Paul then listed the armor: the girdle of truth, the breastplate of righteousness, feet shod with the preparation of the gospel of peace, the shield of faith, the helmet of salvation and the sword of the Spirit. Verse 17 says, And take the helmet of salvation, and the sword of the Spirit, which is the word of God: The sword is the one piece of armor that is used to attack, and it is the Word of God.\n\nYour task is to write Ephesians 2:8 and 9 in your own words, tell why Paul urged believers to keep unity, and name at least four pieces of the armor of God. Then take the four question check.\n\nWe are saved by grace, we are kept by unity, and we stand by the Word. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Ephesians: Grace, Unity and the Armor of God$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Philippians and Colossians: Joy and Christ Above All$j$, $j${"readings": [{"title": "Philippians 2 (King James Version)", "url": "/portal/bible/Philippians/2"}, {"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}, {"title": "Colossians 1 (King James Version)", "url": "/portal/bible/Colossians/1"}, {"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Read Philippians 2, Philippians 4, Colossians 1 and Colossians 3 in the King James Version. Then read this lesson.\n\nPhilippi was the first city in Europe where Paul started a church, and the Philippians loved him and supported him. Paul wrote to them from prison, yet Philippians is full of joy. In chapter 2 he described the humble mind of Christ, who became a servant and died on the cross, and whom God has highly exalted. In chapter 4 he taught believers to rejoice in the Lord, to pray about everything instead of worrying, and to trust that they can do all things through Christ who gives strength. Colossians was written to a church in Asia Minor that was in danger of false teaching. Paul answered by showing that Jesus Christ is Lord over all creation and head of the church, and he urged believers to set their hearts on things above and to work as unto the Lord.\n\nKey words: joy, humility, exalted, preeminence, thanksgiving.\n\nYour task: (1) Tell how Philippians 2 describes the humble mind of Christ. (2) Write Philippians 4:6 and 7 in your own words. (3) Explain what Colossians 1 teaches about who Jesus is.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we study two prison letters that fit together well. The first is Philippians, which is called the letter of joy. The second is Colossians, which shows us that Jesus Christ is above everything.\n\nPhilippi was the city where Paul and Silas sang in the jail at midnight and the jailer was saved, as we saw in Acts 16. The church there was Paul's dear friend, and they sent him gifts when he was in need. Paul wrote back from prison, and the word joy and the word rejoice appear again and again.\n\nIn chapter 2 Paul asked the Philippians to have the mind of Christ. Philippians 2:5 says, Let this mind be in you, which was also in Christ Jesus: Jesus was God, yet He took the form of a servant. Verse 8 says, And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross. Because of this, God lifted Him up. Verse 9 says, Wherefore God also hath highly exalted him, and given him a name which is above every name: And verse 11 says, And that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.\n\nChapter 4 tells us how to live with joy even in hard times. Philippians 4:4 says, Rejoice in the Lord alway: and again I say, Rejoice. Verse 6 says, Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. Verse 7 gives the promise, And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus. Paul also wrote in verse 13, I can do all things through Christ which strengtheneth me. That verse was written by a man in prison who had learned to be content in every state.\n\nNow we turn to Colossians. Colossae was a small city in Asia Minor, and false teachers there were saying that Jesus was not enough. Paul answered by lifting up Christ. Colossians 1:15 says, Who is the image of the invisible God, the firstborn of every creature: Verse 17 says, And he is before all things, and by him all things consist. Verse 18 says, And he is the head of the body, the church: who is the beginning, the firstborn from the dead; that in all things he might have the preeminence. Jesus is Creator, Lord and head of the church, and He must have first place in everything.\n\nPaul then showed what this means for daily life. Colossians 3:2 says, Set your affection on things above, not on things on the earth. And verse 23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men; Whether it is homework, a job or a chore, we do it for the Lord.\n\nYour task is to tell how Philippians 2 describes the humble mind of Christ, write Philippians 4:6 and 7 in your own words, and explain what Colossians 1 teaches about Jesus. Then take the four question check.\n\nJoy comes from the Lord, and He must have first place. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Philippians and Colossians: Joy and Christ Above All$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 First and Second Thessalonians: The Hope of the Lord's Return$j$, $j${"readings": [{"title": "1 Thessalonians 4 (King James Version)", "url": "/portal/bible/1Thessalonians/4"}, {"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}, {"title": "2 Thessalonians 3 (King James Version)", "url": "/portal/bible/2Thessalonians/3"}], "body": "Read 1 Thessalonians 4, 1 Thessalonians 5 and 2 Thessalonians 3 in the King James Version. Then read this lesson.\n\nThessalonica was the capital of Macedonia. Paul preached there on his second journey, and a church was born, but he had to leave quickly because of opposition. Soon after, he wrote 1 and 2 Thessalonians to encourage the young believers. These are among his earliest letters. Paul comforted those who had lost loved ones by teaching that Jesus will return, that the dead in Christ will rise first, and that believers will be with the Lord forever. He also gave short commands for daily life: rejoice evermore, pray without ceasing and in every thing give thanks. In the second letter he told the believers not to be weary in well doing and to keep working while they wait.\n\nKey words: hope, return, comfort, thanksgiving, faithful.\n\nYour task: (1) Tell what hope Paul gave in 1 Thessalonians 4:13 to 18. (2) List the three short commands in 1 Thessalonians 5:16 to 18. (3) Explain why Paul told the Thessalonians not to be weary in well doing.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we look at the two letters Paul wrote to the church at Thessalonica. Thessalonica was a busy port city and the capital of Macedonia. Paul preached there for only a short time on his second journey, as Acts 17 tells us, and a mob chased him out of town. He worried about the young believers, so he sent Timothy to check on them, and then he wrote them a letter. These are some of the first letters Paul ever wrote.\n\nThe Thessalonians had a question. Some of their loved ones had died, and they wondered what would happen to them. Paul answered with hope. First Thessalonians 4:13 says, But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope. Christians do grieve, but we do not grieve like people without hope.\n\nThen Paul described the return of the Lord. Verse 16 says, For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first: Verse 17 says, Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord. And verse 18 says, Wherefore comfort one another with these words. The promise of the Lord's return is meant to comfort us.\n\nPaul also gave short commands for daily life in chapter 5. First Thessalonians 5:16 says, Rejoice evermore. Verse 17 says, Pray without ceasing. Verse 18 says, In every thing give thanks: for this is the will of God in Christ Jesus concerning you. And verse 21 says, Prove all things; hold fast that which is good. Joy, prayer and thanksgiving are the will of God for every believer.\n\nIn Second Thessalonians Paul wrote again, because some believers thought the Lord's coming was so near that they had stopped working. Paul reminded them in chapter 3 and verse 3, But the Lord is faithful, who shall stablish you, and keep you from evil. He also said in verse 10, For even when we were with you, this we commanded you, that if any would not work, neither should he eat. Waiting for the Lord does not mean being idle. And verse 13 says, But ye, brethren, be not weary in well doing. We keep serving faithfully until He comes.\n\nYour task is to tell what hope Paul gave in 1 Thessalonians 4, list the three short commands in 1 Thessalonians 5:16 to 18, and explain why Paul told the church not to be weary in well doing. Then take the four question check.\n\nThe Lord is coming, so we comfort one another and keep working. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 First and Second Thessalonians: The Hope of the Lord's Return$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 The Pastoral Letters and Philemon$j$, $j${"readings": [{"title": "1 Timothy 4 (King James Version)", "url": "/portal/bible/1Timothy/4"}, {"title": "2 Timothy 3 (King James Version)", "url": "/portal/bible/2Timothy/3"}, {"title": "Titus 2 (King James Version)", "url": "/portal/bible/Titus/2"}, {"title": "Philemon 1 (King James Version)", "url": "/portal/bible/Philemon/1"}], "body": "Read 1 Timothy 4, 2 Timothy 3, Titus 2 and Philemon 1 in the King James Version. Then read this lesson.\n\nThe letters to Timothy and Titus are called the pastoral letters because Paul wrote them to young leaders who were caring for churches. Timothy served at Ephesus and Titus served on the island of Crete. Paul told Timothy not to let anyone despise his youth but to be an example of the believers. In 2 Timothy, which is probably the last letter Paul wrote, he taught that all scripture is given by inspiration of God and is profitable for doctrine, reproof, correction and instruction in righteousness. Near the end of his life Paul wrote that he had fought a good fight, finished his course and kept the faith. In Titus he taught that the grace of God teaches us to live soberly, righteously and godly. Philemon is a short and personal letter in which Paul asked his friend Philemon to receive back Onesimus, who had left, as a brother beloved.\n\nKey words: pastor, example, inspiration, scripture, forgiveness.\n\nYour task: (1) Tell what Paul asked Timothy to be in 1 Timothy 4:12. (2) Write 2 Timothy 3:16 in your own words. (3) Explain what Paul asked Philemon to do for Onesimus.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "This is our last lesson on the letters of Paul. Today we study the letters to Timothy and Titus and the short letter to Philemon. First and Second Timothy and Titus are called the pastoral letters, because Paul wrote them to young leaders who were taking care of churches.\n\nTimothy was Paul's spiritual son. He was probably a young man when Paul invited him to join his travels in Acts 16. Later Timothy served in Ephesus. Paul gave him this advice in First Timothy 4:12, Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity. A young person who lives well can lead others. Paul also reminded him in First Timothy 2:5, For there is one God, and one mediator between God and men, the man Christ Jesus;\n\nSecond Timothy is the last letter we have from Paul. He was in prison again, and he knew his time was short. He told Timothy in 2 Timothy 1:7, For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind. He urged Timothy to keep to the Word. Second Timothy 3:15 says, And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus. And verse 16 says, All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: Verse 17 says the result, That the man of God may be perfect, throughly furnished unto all good works.\n\nAt the end of the letter Paul looked back on his life. In 2 Timothy 4:7 he wrote, I have fought a good fight, I have finished my course, I have kept the faith: And verse 8 says, Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing. Paul finished well, and we are invited to finish well too.\n\nTitus served on the island of Crete, where he was to set the churches in order. Paul reminded him in Titus 2:11, For the grace of God that bringeth salvation hath appeared to all men, And the next verse says that grace teaches us to live soberly, righteously and godly. In Titus 3:5 Paul wrote, Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;\n\nFinally there is Philemon, the shortest of Paul's letters. Philemon was a believer in Colossae, and his servant Onesimus had left him. Onesimus met Paul and became a believer. Paul sent him back with a letter. In Philemon 1:16 Paul asked Philemon to receive him, Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord? And in verse 17 he wrote, If thou count me therefore a partner, receive him as myself. Paul even offered to pay any debt in verse 18, If he hath wronged thee, or oweth thee ought, put that on mine account; This is a picture of forgiveness, and it reminds us of how Christ paid our debt.\n\nYour task is to tell what Paul asked Timothy to be, write 2 Timothy 3:16 in your own words, and explain what Paul asked Philemon to do for Onesimus. Then take the four question check and the Unit 4 quiz.\n\nPaul finished his course, and by God's grace we can finish ours. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 The Pastoral Letters and Philemon$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: One Letter, One Message$j$, $j${"prompt": "Choose one of these letters from this unit: Ephesians, Philippians, Colossians, 1 Thessalonians, 2 Timothy or Philemon. Write one paragraph of 150 to 200 words. Tell who the letter was written to, state its main message, quote one verse from it in the King James Version with the reference, and explain how that message helps a student today.", "rubric": "Total 100. Names the readers and setting of the letter: 20. States the main message accurately: 30. Quotes a verse correctly with the reference and applies it: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: One Letter, One Message$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Joy and Hope in Hard Places$j$, $j${"prompt": "Paul wrote about joy, peace and hope while he was in prison. Think of a time when something in your life was hard or uncertain. Tell how a truth from Paul's letters in this unit, such as Philippians 4:6 and 7 or 1 Thessalonians 5:16 to 18, could help you stay hopeful. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Joy and Hope in Hard Places$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$, $j${"questions": [{"q": "Where was Paul when he wrote Ephesians, Philippians, Colossians and Philemon?", "options": ["On a ship at sea", "In prison", "In Corinth", "In Jerusalem"]}, {"q": "According to Ephesians 2:8, by what are we saved through faith?", "options": ["Good works", "Grace", "The law", "Our own goodness"]}, {"q": "What does Ephesians 4:3 tell believers to keep?", "options": ["The law of Moses", "The Sabbath", "A tenth of the harvest", "The unity of the Spirit in the bond of peace"]}, {"q": "According to Ephesians 6:17, what is the sword of the Spirit?", "options": ["The word of God", "Fasting", "Prayer", "The church"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$These four letters are called the prison letters because Paul wrote them in chains.$j$,$j$Ephesians 2:8 says, For by grace are ye saved through faith.$j$,$j$Paul urged the church to keep the unity of the Spirit in the bond of peace.$j$,$j$The sword of the Spirit is the word of God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$, $j${"questions": [{"q": "What city was the first in Europe where Paul started a church?", "options": ["Athens", "Corinth", "Rome", "Philippi"]}, {"q": "According to Philippians 2:8, how far did Jesus humble Himself?", "options": ["He became a king on earth", "He stayed in heaven", "Unto death, even the death of the cross", "He refused the cross"]}, {"q": "What does Philippians 4:6 tell believers to do instead of being careful for anything?", "options": ["Make requests known unto God by prayer with thanksgiving", "Work harder", "Move to a new city", "Wait in silence"]}, {"q": "According to Colossians 1:18, what is Jesus to the church?", "options": ["A teacher only", "The head of the body", "A guest", "A servant"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,0,1}'::int[], array[$j$Paul started the church at Philippi on his second journey, as Acts 16 records.$j$,$j$Jesus became obedient unto death, even the death of the cross.$j$,$j$Paul taught prayer and thanksgiving instead of worry.$j$,$j$Colossians 1:18 says He is the head of the body, the church.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$, $j${"questions": [{"q": "In what region was the city of Thessalonica?", "options": ["Galilee", "Judea", "Macedonia", "Egypt"]}, {"q": "According to 1 Thessalonians 4:13, why did Paul write about those who are asleep?", "options": ["To ask for an offering", "To teach the law", "To describe a journey", "So that believers would not sorrow as others who have no hope"]}, {"q": "Which of these is one of the short commands in 1 Thessalonians 5:16 to 18?", "options": ["Build a temple", "Travel to Rome", "Pray without ceasing", "Pay your debts"]}, {"q": "What did Paul tell the Thessalonians in 2 Thessalonians 3:13?", "options": ["Leave the city", "Stop meeting together", "Wait without working", "Be not weary in well doing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,3}'::int[], array[$j$Thessalonica was the capital of Macedonia.$j$,$j$Paul wanted the church to have hope about believers who had died.$j$,$j$First Thessalonians 5:17 says, Pray without ceasing.$j$,$j$Paul urged them to keep doing good while they waited for the Lord.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: The Pastoral Letters and Philemon$j$, $j${"questions": [{"q": "Why are the letters to Timothy and Titus called the pastoral letters?", "options": ["They were written to farmers", "They were written to Jewish priests", "They were written to young leaders who cared for churches", "They were written to Roman officials"]}, {"q": "According to 1 Timothy 4:12, what was Timothy to be?", "options": ["A ruler over the church", "A silent observer", "A tax collector", "An example of the believers"]}, {"q": "According to 2 Timothy 3:16, all scripture is given by what?", "options": ["Tradition", "The elders of Israel", "Roman law", "Inspiration of God"]}, {"q": "What did Paul ask Philemon to do about Onesimus?", "options": ["Receive him as a brother beloved", "Punish him", "Sell him", "Send him away"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Pastoral Letters and Philemon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,0}'::int[], array[$j$Paul wrote them to Timothy and Titus, who were caring for churches.$j$,$j$Paul told Timothy to be an example of the believers.$j$,$j$All scripture is given by inspiration of God.$j$,$j$Paul asked Philemon to receive Onesimus as a brother beloved.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Pastoral Letters and Philemon$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$, $j${"questions": [{"q": "Why are Ephesians, Philippians, Colossians and Philemon called the prison letters?", "options": ["They were found in a prison", "Paul wrote them while he was in prison", "They were written to prisoners", "They are about a jailer"]}, {"q": "What does Ephesians 6:17 call the sword of the Spirit?", "options": ["The church", "Fasting", "The law", "The word of God"]}, {"q": "Which letter is known as the letter of joy?", "options": ["Colossians", "Titus", "Philippians", "Philemon"]}, {"q": "What hope did Paul give the Thessalonians in 1 Thessalonians 4?", "options": ["That persecution would end tomorrow", "That the church would become rich", "That the dead in Christ shall rise and we shall ever be with the Lord", "That the law would be restored"]}, {"q": "What did Paul say in 2 Timothy 4:7 at the end of his life?", "options": ["I have built a great church", "I have escaped prison", "I have fought a good fight, I have finished my course, I have kept the faith", "I have finished the temple"]}, {"q": "What did Paul ask Philemon to do in his short letter?", "options": ["Send money to Jerusalem", "Receive Onesimus as a brother", "Close the church at Colossae", "Come to Rome"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2,2,1}'::int[], array[$j$Paul wrote these four letters from prison.$j$,$j$The sword of the Spirit is the word of God.$j$,$j$Philippians is full of joy and rejoicing.$j$,$j$Paul comforted the church with the promise of the Lord's return.$j$,$j$Paul looked back on his life and said he had kept the faith.$j$,$j$Paul asked Philemon to receive Onesimus back as a brother beloved.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$ on conflict (item_id) do nothing;
